#[cfg(test)]
mod tests {
    use super::*;

    fn enabled_config() -> AutogenConfig {
        AutogenConfig {
            enabled: true,
            threshold: 3,
            max_pending: 10,
            install_dir: None,
            learner: None,
        }
    }

    fn disabled_config() -> AutogenConfig {
        AutogenConfig::default()
    }

    // -- AutogenConfig tests --

    #[test]
    fn config_default_is_disabled() {
        let config = AutogenConfig::default();
        assert!(!config.enabled);
        assert_eq!(config.threshold, 3);
        assert_eq!(config.max_pending, 10);
        assert!(config.learner.is_none());
    }

    #[test]
    fn config_with_learner_attaches_arc() {
        let learner = Arc::new(TrajectoryLearner::new(
            crate::pipeline::learner::TrajectoryLearnerConfig::default(),
        ));
        let config = AutogenConfig::default().with_learner(Arc::clone(&learner));
        assert!(config.learner.is_some());
        assert_eq!(
            Arc::as_ptr(config.learner.as_ref().unwrap()),
            Arc::as_ptr(&learner)
        );
    }

    #[test]
    fn config_install_dir_default() {
        let config = AutogenConfig::default();
        let dir = config.install_dir();
        assert!(dir.to_string_lossy().contains(".clawft"));
        assert!(dir.to_string_lossy().contains("skills"));
    }

    // -- ToolCallPattern tests --

    #[test]
    fn pattern_suggested_name() {
        let pattern = ToolCallPattern::new(vec!["read_file".into(), "edit_file".into()]);
        let name = pattern.suggested_name();
        assert!(name.contains("read_file"));
        assert!(name.contains("edit_file"));
        assert!(name.ends_with("-auto"));
    }

    #[test]
    fn pattern_suggested_name_long_truncated() {
        let tools: Vec<String> = (0..20).map(|i| format!("tool_{i}")).collect();
        let pattern = ToolCallPattern::new(tools);
        let name = pattern.suggested_name();
        assert!(name.len() <= 65, "name too long: {}", name.len());
    }

    #[test]
    fn pattern_empty() {
        let pattern = ToolCallPattern::new(vec![]);
        assert!(pattern.is_empty());
        assert_eq!(pattern.len(), 0);
        assert_eq!(pattern.suggested_name(), "unnamed-skill");
    }

    // -- PatternDetector tests --

    #[test]
    fn detector_disabled_records_nothing() {
        let mut detector = PatternDetector::new(disabled_config());
        detector.record_tool_call("read_file");
        detector.record_tool_call("edit_file");
        let candidates = detector.detect_candidates();
        assert!(candidates.is_empty());
    }

    #[test]
    fn detector_does_not_fire_below_threshold() {
        let mut detector = PatternDetector::new(enabled_config());
        // Record pattern twice (below threshold of 3)
        for _ in 0..2 {
            detector.record_tool_call("read_file");
            detector.record_tool_call("edit_file");
        }
        let candidates = detector.detect_candidates();
        assert!(candidates.is_empty());
    }

    #[test]
    fn detector_fires_at_threshold() {
        let mut detector = PatternDetector::new(enabled_config());
        // Record pattern 3 times (at threshold)
        for _ in 0..3 {
            detector.record_tool_call("read_file");
            detector.record_tool_call("edit_file");
        }
        let candidates = detector.detect_candidates();
        assert!(!candidates.is_empty(), "should detect at least one pattern");
    }

    #[test]
    fn detector_does_not_re_report() {
        let mut detector = PatternDetector::new(enabled_config());
        for _ in 0..5 {
            detector.record_tool_call("read_file");
            detector.record_tool_call("edit_file");
        }
        let first = detector.detect_candidates();
        assert!(!first.is_empty());

        // Second call should not re-report the same pattern
        let second = detector.detect_candidates();
        assert!(second.is_empty(), "should not re-report same pattern");
    }

    #[test]
    fn detector_reset_clears_state() {
        let mut detector = PatternDetector::new(enabled_config());
        for _ in 0..3 {
            detector.record_tool_call("a");
            detector.record_tool_call("b");
        }
        let _ = detector.detect_candidates();
        detector.reset();

        // After reset, same pattern should be detected again
        for _ in 0..3 {
            detector.record_tool_call("a");
            detector.record_tool_call("b");
        }
        let candidates = detector.detect_candidates();
        assert!(!candidates.is_empty());
    }

    #[test]
    fn detector_configurable_threshold() {
        let config = AutogenConfig {
            enabled: true,
            threshold: 5,
            ..Default::default()
        };
        let mut detector = PatternDetector::new(config);

        for _ in 0..4 {
            detector.record_tool_call("x");
            detector.record_tool_call("y");
        }
        assert!(detector.detect_candidates().is_empty(), "below threshold");

        detector.record_tool_call("x");
        detector.record_tool_call("y");
        assert!(!detector.detect_candidates().is_empty(), "at threshold");
    }

    // -- Skill generation tests --

    #[test]
    fn generate_skill_md_valid() {
        let pattern = ToolCallPattern::new(vec![
            "read_file".into(),
            "edit_file".into(),
            "write_file".into(),
        ]);
        let candidate = generate_skill_md(&pattern);

        assert!(candidate.name.contains("auto"));
        assert_eq!(candidate.state, CandidateState::Pending);
        assert!(candidate.skill_md.contains("---"));
        assert!(candidate.skill_md.contains("read_file"));
        assert!(candidate.skill_md.contains("edit_file"));
        assert!(candidate.skill_md.contains("write_file"));
        assert!(candidate.skill_md.contains("autogenerated: true"));
        assert!(candidate.skill_md.contains("user-invocable: false"));
    }

    #[test]
    fn generate_skill_md_description_contains_tools() {
        let pattern = ToolCallPattern::new(vec!["a".into(), "b".into()]);
        let candidate = generate_skill_md(&pattern);
        assert!(candidate.description.contains("`a`"));
        assert!(candidate.description.contains("`b`"));
    }

    // -- Install/approve/reject tests --

    #[test]
    fn install_pending_skill_creates_files() {
        let dir = std::env::temp_dir().join("clawft_autogen_install_test");
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::create_dir_all(&dir);

        let pattern = ToolCallPattern::new(vec!["read_file".into(), "edit_file".into()]);
        let candidate = generate_skill_md(&pattern);

        let result = install_pending_skill(&candidate, &dir);
        assert!(result.is_ok());

        let skill_dir = result.unwrap();
        assert!(skill_dir.join("SKILL.md").exists());
        assert!(skill_dir.join(".pending").exists());
        assert!(is_pending(&skill_dir));

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn approve_skill_removes_marker() {
        let dir = std::env::temp_dir().join("clawft_autogen_approve_test");
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::create_dir_all(&dir);

        let pattern = ToolCallPattern::new(vec!["a".into(), "b".into()]);
        let candidate = generate_skill_md(&pattern);
        let skill_dir = install_pending_skill(&candidate, &dir).unwrap();

        assert!(is_pending(&skill_dir));
        assert!(approve_skill(&skill_dir).is_ok());
        assert!(!is_pending(&skill_dir));
        assert!(skill_dir.join("SKILL.md").exists());

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn reject_skill_removes_directory() {
        let dir = std::env::temp_dir().join("clawft_autogen_reject_test");
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::create_dir_all(&dir);

        let pattern = ToolCallPattern::new(vec!["x".into(), "y".into()]);
        let candidate = generate_skill_md(&pattern);
        let skill_dir = install_pending_skill(&candidate, &dir).unwrap();

        assert!(skill_dir.exists());
        assert!(reject_skill(&skill_dir).is_ok());
        assert!(!skill_dir.exists());

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn approve_non_pending_fails() {
        let dir = std::env::temp_dir().join("clawft_autogen_approve_nopend");
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::create_dir_all(&dir);

        // No .pending marker
        let result = approve_skill(&dir);
        assert!(result.is_err());
        assert!(result.unwrap_err().contains("not in pending state"));

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn generated_skill_has_minimal_permissions() {
        let pattern = ToolCallPattern::new(vec!["read_file".into()]);
        let candidate = generate_skill_md(&pattern);

        // Generated skill should NOT have shell, network, or broad FS access
        assert!(!candidate.skill_md.contains("shell: true"));
        assert!(!candidate.skill_md.contains("network:"));
        // user-invocable should be false for safety
        assert!(candidate.skill_md.contains("user-invocable: false"));
        // WEFT-75: explicit minimal filesystem allowlist
        assert!(candidate.skill_md.contains("filesystem:"));
        assert!(candidate.skill_md.contains("readable-paths:"));
        assert!(candidate.skill_md.contains("writable-paths:"));
        assert!(candidate.skill_md.contains("allow-create: false"));
        assert!(candidate.skill_md.contains("allow-delete: false"));
        assert!(candidate.skill_md.contains(&format!("- {AUTOGEN_WORKSPACE_PATH}")));
    }

    // -- Filesystem allowlist (WEFT-75) --

    #[test]
    fn generate_skill_md_emits_explicit_minimal_allowlist() {
        let pattern = ToolCallPattern::new(vec!["read_file".into(), "edit_file".into()]);
        let candidate = generate_skill_md(&pattern);
        let minimal = SkillFilesystemAllowlist::minimal_autogen();

        // Round-trip via skills_v2 parser so metadata.filesystem is populated.
        let skill = crate::agent::skills_v2::parse_skill_md(&candidate.skill_md, None)
            .expect("generated SKILL.md must parse");
        assert!(is_autogenerated_skill(&skill));
        let fs = SkillFilesystemAllowlist::from_skill(&skill)
            .expect("autogen skill must carry filesystem allowlist");
        assert_eq!(fs, minimal);
        assert_eq!(fs.readable_paths, vec![AUTOGEN_WORKSPACE_PATH]);
        assert_eq!(fs.writable_paths, vec![AUTOGEN_WORKSPACE_PATH]);
        assert!(!fs.allow_create);
        assert!(!fs.allow_delete);
    }

    #[test]
    fn broader_host_effective_allowlist_is_minimum() {
        // Synthetic broader-perm host loads autogen skill; effective is skill minimum.
        let pattern = ToolCallPattern::new(vec!["read_file".into()]);
        let candidate = generate_skill_md(&pattern);
        let skill = crate::agent::skills_v2::parse_skill_md(&candidate.skill_md, None).unwrap();

        let host = SkillFilesystemAllowlist {
            readable_paths: vec![
                ".".into(),
                "/home".into(),
                "/tmp".into(),
                "/var/log".into(),
            ],
            writable_paths: vec![".".into(), "/tmp".into(), "/home/out".into()],
            allow_create: true,
            allow_delete: true,
        };

        let effective = effective_filesystem_on_load(&skill, &host);
        let minimal = SkillFilesystemAllowlist::minimal_autogen();

        assert_eq!(
            effective, minimal,
            "broader host must not widen autogen skill FS beyond minimal"
        );
        assert!(
            effective.is_subset_of(&host),
            "effective must never exceed host"
        );
        assert!(
            effective.is_subset_of(&minimal),
            "effective must not exceed skill-declared minimum"
        );
        assert!(!effective.allow_create);
        assert!(!effective.allow_delete);
    }

    #[test]
    fn narrower_host_further_restricts_autogen_skill() {
        let pattern = ToolCallPattern::new(vec!["read_file".into()]);
        let candidate = generate_skill_md(&pattern);
        let skill = crate::agent::skills_v2::parse_skill_md(&candidate.skill_md, None).unwrap();

        // Host does not allow workspace "."; only /tmp.
        let host = SkillFilesystemAllowlist {
            readable_paths: vec!["/tmp".into()],
            writable_paths: vec!["/tmp".into()],
            allow_create: false,
            allow_delete: false,
        };

        let effective = effective_filesystem_on_load(&skill, &host);
        // Intersection of {.} ∩ {/tmp} is empty — skill cannot exceed host.
        assert!(effective.readable_paths.is_empty());
        assert!(effective.writable_paths.is_empty());
        assert!(effective.is_subset_of(&host));
    }

    #[test]
    fn intersect_filesystem_allowlist_ands_boolean_flags() {
        let skill = SkillFilesystemAllowlist {
            readable_paths: vec![".".into()],
            writable_paths: vec![".".into()],
            allow_create: true,
            allow_delete: false,
        };
        let host = SkillFilesystemAllowlist {
            readable_paths: vec![".".into()],
            writable_paths: vec![".".into()],
            allow_create: false,
            allow_delete: true,
        };
        let effective = intersect_filesystem_allowlist(&skill, &host);
        assert!(!effective.allow_create);
        assert!(!effective.allow_delete);
    }

    #[test]
    fn non_autogen_skill_without_fs_defers_to_host() {
        let skill = SkillDefinition::new("manual", "hand-written skill");
        let host = SkillFilesystemAllowlist {
            readable_paths: vec!["/workspace".into()],
            writable_paths: vec!["/workspace".into()],
            allow_create: true,
            allow_delete: false,
        };
        let effective = effective_filesystem_on_load(&skill, &host);
        assert_eq!(effective, host);
    }

    #[test]
    fn legacy_autogen_without_fs_block_uses_minimal_defaults() {
        // Older generated skills only had autogenerated: true.
        let mut skill = SkillDefinition::new("legacy-auto", "old autogen skill");
        skill
            .metadata
            .insert("autogenerated".into(), serde_json::json!(true));
        let host = SkillFilesystemAllowlist {
            readable_paths: vec![".".into(), "/extra".into()],
            writable_paths: vec![".".into(), "/extra".into()],
            allow_create: true,
            allow_delete: true,
        };
        let effective = effective_filesystem_on_load(&skill, &host);
        assert_eq!(effective, SkillFilesystemAllowlist::minimal_autogen());
    }

    #[test]
    fn is_enabled_reflects_config() {
        let enabled = PatternDetector::new(enabled_config());
        assert!(enabled.is_enabled());

        let disabled = PatternDetector::new(disabled_config());
        assert!(!disabled.is_enabled());
    }

    // -- Trajectory-based improvement tests --

    fn make_test_learner() -> TrajectoryLearner {
        use crate::pipeline::learner::TrajectoryLearnerConfig;
        use crate::pipeline::traits::{
            ChatRequest, LlmMessage, QualityScore, RoutingDecision, Trajectory,
        };
        use clawft_types::provider::{ContentBlock, LlmResponse, StopReason, Usage};

        let learner = TrajectoryLearner::new(TrajectoryLearnerConfig::default());

        let make_traj = |overall: f32, content: &str| Trajectory {
            request: ChatRequest {
                messages: vec![LlmMessage {
                    role: "user".into(),
                    content: content.into(),
                    tool_call_id: None,
                    tool_calls: None,
                }],
                tools: vec![],
                model: None,
                max_tokens: None,
                temperature: None,
                auth_context: None,
                complexity_boost: 0.0,
                tool_choice: None,
            },
            routing: RoutingDecision::default(),
            response: LlmResponse {
                id: "r".into(),
                content: vec![ContentBlock::Text { text: "ok".into() }],
                stop_reason: StopReason::EndTurn,
                usage: Usage {
                    input_tokens: 5,
                    output_tokens: 2,
                    total_tokens: 0,
                },
                metadata: std::collections::HashMap::new(),
            },
            quality: QualityScore {
                overall,
                relevance: overall,
                coherence: overall,
            },
        };

        // Record some good and poor trajectories
        use crate::pipeline::traits::LearningBackend;
        learner.record(&make_traj(0.95, "Write a function to sort a list"));
        learner.record(&make_traj(0.9, "Explain recursion with examples"));
        learner.record(&make_traj(0.3, "Fix the bug"));
        learner.record(&make_traj(0.4, "Summarize article"));

        learner
    }

    #[test]
    fn improve_skill_instructions_with_patterns() {
        let learner = make_test_learner();
        let original = "Use the read_file tool\nCheck the output";
        let improved = improve_skill_instructions(original, &learner);

        // Should be different since we have trajectory data
        assert!(!improved.is_empty());
    }

    #[test]
    fn improve_skill_instructions_empty_learner_returns_original() {
        use crate::pipeline::learner::TrajectoryLearnerConfig;
        let learner = TrajectoryLearner::new(TrajectoryLearnerConfig::default());
        let original = "Use the read_file tool";
        let result = improve_skill_instructions(original, &learner);
        assert_eq!(result, original);
    }

    #[test]
    fn generate_skill_md_with_learning_no_learner() {
        let pattern = ToolCallPattern::new(vec!["a".into(), "b".into()]);
        let candidate = generate_skill_md_with_learning(&pattern, None);
        assert!(candidate.skill_md.contains("autogenerated: true"));
        let baseline = generate_skill_md(&pattern);
        assert_eq!(candidate.skill_md, baseline.skill_md);
    }

    #[test]
    fn generate_skill_md_with_learning_uses_learner() {
        let learner = make_test_learner();
        let pattern = ToolCallPattern::new(vec!["read_file".into(), "edit_file".into()]);
        let baseline = generate_skill_md(&pattern);
        let candidate = generate_skill_md_with_learning(&pattern, Some(&learner));

        // Frontmatter + tools remain valid.
        assert!(candidate.skill_md.contains("read_file"));
        assert!(candidate.skill_md.contains("autogenerated: true"));
        assert!(candidate.skill_md.contains("filesystem:"));
        assert!(!candidate.skill_md.is_empty());

        // Learning mutates the body using successful trajectories
        // (make_test_learner seeds quality ≥ 0.8 → AddExamples strategy).
        assert_ne!(
            candidate.skill_md, baseline.skill_md,
            "trajectory learning must change SKILL.md body"
        );
        assert!(
            candidate.skill_md.contains("Successful Examples")
                || candidate.skill_md.contains("Write a function")
                || candidate.skill_md.contains("Explain recursion")
                || candidate.skill_md.contains("Step "),
            "expected example injection or rephrase markers in improved SKILL.md: {}",
            candidate.skill_md
        );
    }

    /// End-to-end WEFT-66: AutogenConfig with an active TrajectoryLearner
    /// drives learning-based generation the same way the agent loop does.
    #[test]
    fn e2e_autogen_config_learner_improves_skill_md() {
        let learner = Arc::new(make_test_learner());
        let config = AutogenConfig {
            enabled: true,
            threshold: 2,
            max_pending: 10,
            install_dir: None,
            learner: Some(Arc::clone(&learner)),
        };
        assert!(config.learner.is_some());

        let mut detector = PatternDetector::new(config);
        // Threshold=2: record the same 2-tool sequence twice.
        for _ in 0..2 {
            detector.record_tool_call("read_file");
            detector.record_tool_call("edit_file");
        }
        let candidates = detector.detect_candidates();
        assert!(
            !candidates.is_empty(),
            "pattern detector should emit at least one candidate"
        );

        let pattern = &candidates[0];
        let baseline = generate_skill_md(pattern);
        let improved = generate_skill_md_with_learning(pattern, detector.learner());

        assert_ne!(improved.skill_md, baseline.skill_md);
        assert!(improved.skill_md.contains("read_file"));
        assert!(improved.skill_md.contains("autogenerated: true"));
        assert!(
            improved.skill_md.contains("Successful Examples")
                || improved.skill_md.contains("Write a function")
                || improved.skill_md.contains("Explain recursion"),
            "improved body should reflect synthetic high-quality trajectories: {}",
            improved.skill_md
        );
    }
}
